<section class="slide" data-page="05 / 09">
  <div class="slide-content">
    <div class="kicker">Finding 3 · token compression</div>
    <div class="row wide-right">
      <div>
        <h2>Pixel shuffle at r=4 cuts visual tokens 16×.</h2>
        <ul class="bullets">
          <li><b>Mechanism:</b> rearrange spatial features into channels.</li>
          <li><b>Reduction:</b> visual token count decreases by r².</li>
          <li><b>Small models:</b> benefit from aggressive r=4 compression.</li>
          <li><b>Larger models:</b> use r=2 in the paper design.</li>
        </ul>
      </div>
      <div class="panel">
        <div class="shuffle-grid">
          <div>
            <div class="tokens">
              <span class="token"></span><span class="token"></span><span class="token"></span><span class="token"></span>
              <span class="token"></span><span class="token"></span><span class="token"></span><span class="token"></span>
              <span class="token"></span><span class="token"></span><span class="token"></span><span class="token"></span>
              <span class="token"></span><span class="token"></span><span class="token"></span><span class="token"></span>
            </div>
            <div class="caption">16 spatial tokens</div>
          </div>
          <div class="arrow-big">→</div>
          <div>
            <div class="compressed">
              <span class="channel"></span><span class="channel"></span><span class="channel"></span><span class="channel"></span>
              <span class="channel"></span><span class="channel"></span><span class="channel"></span><span class="channel"></span>
              <span class="channel"></span><span class="channel"></span><span class="channel"></span><span class="channel"></span>
              <span class="channel"></span><span class="channel"></span><span class="channel"></span><span class="channel"></span>
            </div>
            <div class="caption">1 token · 16 channels</div>
          </div>
        </div>
        <div class="eq">r = 4 ⇒ r² = 16× fewer tokens</div>
        <div class="visual-frame" style="margin-top:clamp(.45rem,.9vw,.8rem)">
          <img src="../benchmark/assets/figure_6.jpg" alt="Pixel shuffle diagram" style="max-height:min(22vh,170px)">
        </div>
      </div>
    </div>
  </div>
</section>

<section class="slide" data-page="06 / 09">
  <div class="slide-content">
    <div class="kicker">Finding 2 · context scaling</div>
